<?php $u=require_user();$p=$u;?><section class="page form-page"><a href="dashboard.php">← My workspace</a><h1>Your professional profile.</h1><p>Account ID: HST-<?=h($u['id'])?> · <?=h($u['email'])?></p><form method="post"><?=csrf()?><input type="hidden" name="action" value="profile-details"><?php foreach(['name'=>$u['role']==='employer'?'Company name':'Full name','title'=>'Professional title','location'=>'Location','website'=>'Website or portfolio URL'] as $key=>$label):?><label for="<?=h($key)?>"><?=h($label)?></label><input id="<?=h($key)?>" name="<?=h($key)?>" maxlength="<?=$key==='website'?255:($key==='name'?100:120)?>" <?=$key==='name'?'required minlength="2"':''?> value="<?=h($p[$key]??'')?>"><?php endforeach;?><label for="bio"><?=$u['role']==='employer'?'About your company':'Experience and background'?></label><textarea id="bio" name="bio" maxlength="3000" rows="7"><?=h($p['bio'])?></textarea><?php if($u['role']==='seeker'):?><label for="field">Field of work</label><select id="field" name="field"><?php foreach($categories as $c):?><option <?=$c===$p['field']?'selected':''?>><?=h($c)?></option><?php endforeach;?></select><div class="form-grid"><div><label for="age">Age (optional)</label><input id="age" name="age" type="number" min="16" max="100" value="<?=h($p['age']??'')?>"></div><div><label for="experience">Experience in years</label><input id="experience" name="experience_years" type="number" min="0" max="60" step="0.1" value="<?=h($p['experience_years']??'')?>"></div></div><label for="education">Education and certifications</label><textarea id="education" name="education" maxlength="500" rows="3"><?=h($p['education']??'')?></textarea><label for="work-history">Work experience and projects</label><textarea id="work-history" name="work_history" maxlength="6000" rows="7"><?=h($p['work_history']??'')?></textarea><label for="skills">Skills</label><textarea id="skills" name="skills" maxlength="2000" rows="4" aria-describedby="profile-skills-help"><?=h($p['skills'])?></textarea><small id="profile-skills-help">Separate skills with commas. Include tools, languages, methods and certifications. Up to 2,000 characters. Optional age and experience details are shared with employers who can view your profile; age is not used in skill ranking.</small><label><input class="checkbox" type="checkbox" name="discoverable" value="1" <?=$p['discoverable']?'checked':''?>> Let signed-in employers find my profile</label><small>Employers can see your name, field, skills, location and portfolio. Your email is shared with employers you apply to or whose offer you accept. Applications already sent remain visible to their employer.</small><?php endif;?><button class="button">Save profile ↗</button></form><?php require __DIR__ . '/resume-view.php';?></section>
